window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cedac5abe531df36"]={"versions": [{"id": "FIG-cedac5abe531df36", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- und Artefakt-Workflow-Diagramm im Kontext der AUTOSAR Adaptive Platform Methodology (Methoden- und Prozessmodell). Das Diagramm spezifiziert die Aktivität „Develop Adaptive Platform-level Software“ im Bereich der Plattform-Software-Entwicklung (Tier 2) inklusive der beteiligten Rollen, Eingangsartefakte und resultierenden Arbeitsergebnisse.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität:</p>\n<ul class=\"fig-list\">\n<li>Aktivität <code>Develop Adaptive Platform-level Software</code> (zentraler Prozessknoten).</li>\n</ul>\n<p class=\"fig-p\">Akteure und Rollen:</p>\n<ul class=\"fig-list\">\n<li>Übergeordnete Stakeholder-Rolle: <code>Tier 2</code>.</li>\n<li>Spezifische Rollen (beide über stereotype <code>«performs»</code> mit der Aktivität verknüpft):</li>\n<li><code>+Platform Software Designer</code></li>\n<li><code>+Platform Software Developer</code></li>\n</ul>\n<p class=\"fig-p\">Eingangsartefakte (<code>«input»</code>):</p>\n<ul class=\"fig-list\">\n<li><code>Autosar AP Standard Package</code> (Kardinalität <code>0..1</code>): Spezifikations- bzw. Modellpaket der AUTOSAR Adaptive Platform.</li>\n<li><code>Middleware Library Header Files</code> (Kardinalität <code>0..*</code>): C++ Header-Dateien der Middleware-Bibliotheken.</li>\n</ul>\n<p class=\"fig-p\">Ausgangsartefakte (<code>«output»</code>):</p>\n<ul class=\"fig-list\">\n<li><code>Platform Object Code</code> (Kardinalität <code>1..*</code>): Kompilierter Objektcode bzw. Binärdateien der Plattform-Module/Executables.</li>\n<li><code>Main Function</code> (Kardinalität <code>1</code>): Quellcode bzw. Implementierung der Einstiegsfunktion für das jeweilige Plattform-Executable.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Initiierung: Die Rollen <code>Platform Software Designer</code> und <code>Platform Software Developer</code> (zugeordnet zu Tier 2) führen die Aktivität <code>Develop Adaptive Platform-level Software</code> aus.</li>\n<li>Artefaktkonsum: Als optionaler Input wird das <code>Autosar AP Standard Package</code> (<code>0..1</code>) herangezogen; zudem werden beliebig viele <code>Middleware Library Header Files</code> (<code>0..*</code>) als Programmierschnittstellen eingebunden.</li>\n<li>Verarbeitung: Entwicklung und Erstellung der plattformspezifischen Executables (Platform-level Applications), die entweder auf Software-Komponenten mit standardisierten Service-Interfaces basieren oder direkt ohne Komponentenmodell realisiert werden.</li>\n<li>Artefakterzeugung: Erzeugung genau einer <code>Main Function</code> (<code>1</code>) für das Executable sowie mindestens eines <code>Platform Object Code</code>-Artefakts (<code>1..*</code>) zur späteren Instanziierung und Ausführung auf der Zielmaschine.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Verbindliche Rollen- und Verantwortungszuordnung für Plattformzulieferer (Tier 2).</li>\n<li>Normative Mindestanforderung an die Artefakterzeugung: Zu jedem entwickelten Platform-level Executable muss zwingend eine <code>Main Function</code> (Kardinalität 1) bereitgestellt werden.</li>\n<li>Die Kompilierung erfordert mindestens ein Binärartefakt (<code>Platform Object Code</code>, <code>1..*</code>).</li>\n<li>Die Verwendung des <code>Autosar AP Standard Package</code> ist methodisch optional (<code>0..1</code>), ebenso wie die Einbindung spezifischer <code>Middleware Library Header Files</code> (<code>0..*</code>), falls die Plattformmodule autark implementiert sind.</li>\n</ul>"}, {"id": "FIG-c0e7842d81006d21", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- und Artefakt-Workflow-Diagramm im Kontext der AUTOSAR Adaptive Platform Methodology (Methoden- und Prozessmodell). Das Diagramm spezifiziert die Aktivität „Develop Adaptive Platform-level Software“ im Bereich der Plattform-Software-Entwicklung (Tier 2) inklusive der beteiligten Rollen, Eingangsartefakte und resultierenden Arbeitsergebnisse.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität:</p>\n<ul class=\"fig-list\">\n<li>Aktivität <code>Develop Adaptive Platform-level Software</code> (zentraler Prozessknoten).</li>\n</ul>\n<p class=\"fig-p\">Akteure und Rollen:</p>\n<ul class=\"fig-list\">\n<li>Übergeordnete Stakeholder-Rolle: <code>Tier 2</code>.</li>\n<li>Spezifische Rollen (beide über stereotype <code>«performs»</code> mit der Aktivität verknüpft):</li>\n<li><code>+Platform Software Designer</code></li>\n<li><code>+Platform Software Developer</code></li>\n</ul>\n<p class=\"fig-p\">Eingangsartefakte (<code>«input»</code>):</p>\n<ul class=\"fig-list\">\n<li><code>Autosar AP Standard Package</code> (Kardinalität <code>0..1</code>): Spezifikations- bzw. Modellpaket der AUTOSAR Adaptive Platform.</li>\n<li><code>Middleware Library Header Files</code> (Kardinalität <code>0..*</code>): C++ Header-Dateien der Middleware-Bibliotheken.</li>\n</ul>\n<p class=\"fig-p\">Ausgangsartefakte (<code>«output»</code>):</p>\n<ul class=\"fig-list\">\n<li><code>Platform Object Code</code> (Kardinalität <code>1..*</code>): Kompilierter Objektcode bzw. Binärdateien der Plattform-Module/Executables.</li>\n<li><code>Main Function</code> (Kardinalität <code>1</code>): Quellcode bzw. Implementierung der Einstiegsfunktion für das jeweilige Plattform-Executable.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Initiierung: Die Rollen <code>Platform Software Designer</code> und <code>Platform Software Developer</code> (zugeordnet zu Tier 2) führen die Aktivität <code>Develop Adaptive Platform-level Software</code> aus.</li>\n<li>Artefaktkonsum: Als optionaler Input wird das <code>Autosar AP Standard Package</code> (<code>0..1</code>) herangezogen; zudem werden beliebig viele <code>Middleware Library Header Files</code> (<code>0..*</code>) als Programmierschnittstellen eingebunden.</li>\n<li>Verarbeitung: Entwicklung und Erstellung der plattformspezifischen Executables (Platform-level Applications), die entweder auf Software-Komponenten mit standardisierten Service-Interfaces basieren oder direkt ohne Komponentenmodell realisiert werden.</li>\n<li>Artefakterzeugung: Erzeugung genau einer <code>Main Function</code> (<code>1</code>) für das Executable sowie mindestens eines <code>Platform Object Code</code>-Artefakts (<code>1..*</code>) zur späteren Instanziierung und Ausführung auf der Zielmaschine.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Verbindliche Rollen- und Verantwortungszuordnung für Plattformzulieferer (Tier 2).</li>\n<li>Normative Mindestanforderung an die Artefakterzeugung: Zu jedem entwickelten Platform-level Executable muss zwingend eine <code>Main Function</code> (Kardinalität 1) bereitgestellt werden.</li>\n<li>Die Kompilierung erfordert mindestens ein Binärartefakt (<code>Platform Object Code</code>, <code>1..*</code>).</li>\n<li>Die Verwendung des <code>Autosar AP Standard Package</code> ist methodisch optional (<code>0..1</code>), ebenso wie die Einbindung spezifischer <code>Middleware Library Header Files</code> (<code>0..*</code>), falls die Plattformmodule autark implementiert sind.</li>\n</ul>"}], "trans": [{"from": "FIG-cedac5abe531df36", "to": "FIG-c0e7842d81006d21", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
